<?php
/** Slice 8 — overrides (projection.md "Proof": Overrides): a factor, a quantity, factor and quantity together refused in words, the agent's proposal (status proposed, the Manager told, no effect until set), set, dismiss, remove, the right, the log. */
require __DIR__ . '/lib.php';
$w = projection_world();
reset_projection();
$a0 = last_activity_id();
$marco = person(27);
$dana = person(30);
$sand = $w['mi_sand'];
$d3 = day(3); $d4 = day(4); $d5 = day(5);
$cell = fn (string $d, int $item = 0) => q('SELECT * FROM ri_item_forecast(101, :i, :d::date)', ['i' => $item ?: $sand, 'd' => $d])[0];
$base3 = (float) one('SELECT ri_forecast_baseline(101, :i, :d::date)', ['i' => $sand, 'd' => $d3]);

echo "1. A factor and a quantity\n";
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.5', 'reason' => 'SMOKE festival']);
$o1 = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && ($r['json']['ok'] ?? false) && str_contains($r['json']['did'] ?? '', '+50 %') && $r['json']['location'] === '/projection/items/' . $sand . '?notice=override', 'Marco sets +50 % on the sandwich for a day: "Override set: +50 % on …", landing on the item');
ok(near($cell($d3)['qty'], $base3 * 1.5, 0.0001) && $cell($d3)['source'] === 'override', 'the cell says override and equals the baseline × 1.5 (' . $base3 . ' → ' . $cell($d3)['qty'] . ')');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d4, 'to_date' => $d4, 'qty' => '77', 'reason' => 'SMOKE catering']);
$o2 = (int) $r['json']['record_id'];
ok(near($cell($d4)['qty'], 77, 0.0001) && $cell($d4)['source'] === 'override', 'a fixed quantity override: 77 that day');
ok(near($cell($d5)['qty'], (float) one('SELECT ri_forecast_baseline(101, :i, :d::date)', ['i' => $sand, 'd' => $d5]), 0.0001) && $cell($d5)['source'] === 'baseline', 'the day after is untouched');

echo "2. The refusals, in words\n";
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.2', 'qty' => '10', 'reason' => 'x']);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'not both'), 'a factor and a quantity together: "Give a factor or a quantity — not both."');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'reason' => 'x']);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'Give a factor'), 'neither: asked for one');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d4, 'to_date' => $d3, 'factor' => '1.2', 'reason' => 'x']);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['to_date']), 'a last day before the first is refused on to_date');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => day(3 + 93), 'factor' => '1.2', 'reason' => 'x']);
ok($r['code'] === 422 && str_contains(json_encode($r['json']), '92 days'), 'a window over 92 days is refused');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '-1', 'reason' => 'x']);
ok($r['code'] === 422, 'a negative factor is refused');
$r = jpost(27, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.2', 'reason' => '']);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['reason']), 'a reason is required');
$r = jpost(27, '/projection/override.php', ['menu_item' => 99999, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.2', 'reason' => 'x']);
ok($r['code'] === 422 && isset($r['json']['error']['fields']['menu_item']), 'a menu item that is not here is refused');
ok(row_count('forecast_overrides') === 2, 'no refusal left a row');

echo "3. The agent proposes; a person decides\n";
$n0 = nid();
$r = apost(42, 9101, '/projection/override-propose.php', ['menu_item' => $sand, 'from_date' => $d5, 'to_date' => $d5, 'factor' => '1.5', 'reason' => 'SMOKE the festival']);
$p1 = (int) ($r['json']['record_id'] ?? 0);
ok($r['code'] === 200 && one('SELECT status FROM forecast_overrides WHERE id = :i', ['i' => $p1]) === 'proposed', 'forecast_override_propose (the Purchasing agent, a run token): status proposed');
ok($cell($d5)['source'] === 'baseline' && near($cell($d5)['qty'], (float) one('SELECT ri_forecast_baseline(101, :i, :d::date)', ['i' => $sand, 'd' => $d5]), 0.0001), 'a proposed override does not count');
$nn = notes(27, 'agent_drafted', $n0);
ok(count($nn) === 1 && str_contains($nn[0]['title'], 'proposes') && str_contains($nn[0]['title'], '+50 %') && (int) $nn[0]['record_id'] === $p1, 'the Manager is told: "SMOKE Buyer proposes +50 % on … for …"');
$lg = activity('forecast.override_propose', $a0);
ok(count($lg) === 1 && $lg[0]['source'] === 'agent' && (int) $lg[0]['actor_member_id'] === 42 && (int) $lg[0]['scope_id'] === 101, 'forecast.override_propose is logged with the agent as actor, source agent');
$h = page($marco, '/projection/items/' . $sand);
ok(has($h, 'id="override-proposals"') && has($h, 'id="override-set-' . $p1 . '"') && has($h, 'id="override-dismiss-' . $p1 . '"') && has($h, 'id="override-row-' . $o1 . '"') && has($h, 'id="override-remove-' . $o1 . '"'), 'the item shows the proposal with Set / Dismiss and the overrides with Remove');
$r = jpost(27, '/projection/override-decide.php', ['override' => $p1, 'decision' => 'set']);
ok($r['code'] === 200 && one('SELECT status FROM forecast_overrides WHERE id = :i', ['i' => $p1]) === 'set' && (int) one('SELECT set_by FROM forecast_overrides WHERE id = :i', ['i' => $p1]) === 27 && $cell($d5)['source'] === 'override', 'Marco sets it: status set, set_by Marco, the cell says override now');
$r = jpost(27, '/projection/override-decide.php', ['override' => $p1, 'decision' => 'dismiss']);
ok($r['code'] === 422 && str_contains($r['json']['error']['message'] ?? '', 'already decided'), 'a decided override cannot be decided again');
$r = apost(42, 9102, '/projection/override-propose.php', ['from_date' => $d4, 'to_date' => $d4, 'factor' => '0.5', 'reason' => 'SMOKE rain']);
$p2 = (int) $r['json']['record_id'];
$r = jpost(27, '/projection/override-decide.php', ['override' => $p2, 'decision' => 'dismiss']);
ok($r['code'] === 200 && one('SELECT status FROM forecast_overrides WHERE id = :i', ['i' => $p2]) === 'dismissed' && near($cell($d4)['qty'], 77, 0.0001), 'dismiss: status dismissed, nothing changes (the quantity override still wins that day)');

echo "4. The precedence, the removal, the rights\n";
$r = jpost(27, '/projection/override.php', ['from_date' => $d4, 'to_date' => $d4, 'factor' => '2', 'reason' => 'SMOKE every item doubles']);
$all = (int) $r['json']['record_id'];
ok($r['json']['location'] === '/projection/?notice=override' && near($cell($d4, $w['mi_soda'])['qty'], 2 * (float) one('SELECT ri_forecast_baseline(101, :i, :d::date)', ['i' => $w['mi_soda'], 'd' => $d4]), 0.0001), 'an override with no menu item covers every item (the soda doubles) and lands on the forecast');
ok(near($cell($d4)['qty'], 77, 0.0001), 'the item\'s own override wins over the all-items one');
ri_sql("INSERT INTO calendar_days (scope_id, on_date, closed) VALUES (101, :d::date, true)", ['d' => $d4]);
ok(near($cell($d4)['qty'], 0, 0) && $cell($d4)['source'] === 'closed', 'a closed day forecasts zero whatever the override says');
ri_sql('DELETE FROM calendar_days');
$r = jpost(27, '/projection/override-remove.php', ['override' => $o1]);
ok($r['code'] === 200 && one('SELECT count(*) FROM forecast_overrides WHERE id = :i', ['i' => $o1]) == 0 && $cell($d3)['source'] === 'baseline', 'remove: the row goes and the forecast is the run\'s (here the baseline) again');
$r = jpost(27, '/projection/override-remove.php', ['override' => $p2]);
ok($r['code'] === 422 && str_contains(json_encode($r['json']), 'in force'), 'only an override in force is removed (a dismissed one is not)');
$r = jpost(30, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.2', 'reason' => 'x']);
ok($r['code'] === 403 && str_contains($r['json']['error']['message'] ?? '', 'does not let you'), 'Dana (Chef, no forecast.adjust) is refused in words naming the right');
$r = jpost(28, '/projection/override-propose.php', ['from_date' => $d3, 'to_date' => $d3, 'factor' => '1.2', 'reason' => 'x']);
ok($r['code'] === 403, 'Bea (Kitchen) may not propose either (purchasing.draft)');
$ov = activity('forecast.override', $a0); $la = json_decode($ov[count($ov) - 1]['after'], true);
ok(count($ov) >= 3 && $la['reason'] === 'SMOKE every item doubles' && array_key_exists('factor', $la) && array_key_exists('menu_item_id', $la), 'forecast.override is logged with the window, the factor or quantity and the reason');
$rm = activity('forecast.override_remove', $a0);
ok(count($rm) === 1 && (int) $rm[0]['scope_id'] === 101, 'forecast.override_remove is logged');
$h = page($marco, '/projection/items/' . $sand);
$f = post($marco, '/projection/override.php', ['menu_item' => $sand, 'from_date' => $d3, 'to_date' => $d3, 'factor' => '1.1', 'reason' => 'SMOKE browser form']);
ok($f['code'] === 302 && str_starts_with($f['location'], '/projection/items/' . $sand), 'the form posts and lands on the item (no JavaScript)');
finish();
